mapper.select:
select mn.*
from Pro_Project_Register mn

    
        and exists (select 1 from SYS_User permission_user
        where permission_user.U_ID = mn.create_uid
        and permission_user.C_ID = #{params.permissionCompanyId})
    
    
        and mn.id = #{params.id}
    
    
        and mn.project_name like concat('%', #{params.projectName}, '%')
    
    
        and mn.project_code like concat('%', #{params.projectCode}, '%')
    
    
        and mn.project_type = #{params.projectType}
    
    
        and mn.investor_name like concat('%', #{params.investorName}, '%')
    
    
        and mn.is_government_investment = #{params.isGovernmentInvestment}
    
    
        and mn.state = #{params.state}
    

order by mn.create_time desc, mn.id desc
